import json, os

BASE = "/home/dev/garden/bench/results/2026-10-12/m1-ngram/replay"

def summarize(cfg):
    d = os.path.join(BASE, cfg)
    rows = [json.loads(l) for l in open(f"{d}/requests.jsonl")]
    print(f"===== {cfg} =====")
    print(f"total rows: {len(rows)}  (fg={sum(1 for r in rows if r.get('fg_bg')=='fg')})")
    for phase in ["single-agent","single-mem","dual-agent","dual-mem"]:
        fg = [r for r in rows if r["phase"]==phase and r["fg_bg"]=="fg" and "error" not in r]
        if not fg:
            print(f"  {phase}: no fg rows")
            continue
        length_ids = [r["id"] for r in fg if r.get("finish_reason")=="length"]
        def stat(rs):
            p = sum(r["predicted_n"] for r in rs)
            ms = sum(r["predicted_ms"] for r in rs)
            return f"tok={p:.0f} ms={ms/1000:.1f}s tok/s={p/ms*1000:.2f}"
        print(f"  {phase} fg all: {stat(fg)}")
        nlen = [r for r in fg if r.get("finish_reason")!="length"]
        if nlen:
            print(f"  {phase} fg no-length: {stat(nlen)}")
        if length_ids:
            print(f"  {phase} length rows: {length_ids}")
        # draft acceptance summary
        dn = [r.get("draft_n") or 0 for r in fg]
        da = [r.get("draft_n_accepted") or 0 for r in fg]
        if len(dn):
            print(f"  {phase} fg draft: n={sum(dn)} accepted={sum(da)} ratio={sum(da)/max(sum(dn),1):.3f}")

for cfg in ["off-greedy","A-greedy","B-greedy"]:
    try:
        summarize(cfg)
    except Exception as e:
        print(f"{cfg} FAILED: {e}")

