import json

ids = ["inventory-baseline-r1/2/6", "inventory-baseline-r1/2/8",
       "inventory-mem0-r0/0/2", "inventory-mem0-r2/0/2"]
for cfg in ["off-greedy","A-greedy","B-greedy"]:
    rows = [json.loads(l) for l in open(f"{cfg}/requests.jsonl")]
    for i in ids:
        for r in rows:
            if r["id"]==i and r["fg_bg"]=="fg":
                print(f"{cfg} {r['phase']} {i}: fin={r.get('finish_reason')} n={r.get('predicted_n')} ms={r.get('predicted_ms'):.0f} max_tok={r.get('max_tokens')}")
print()
# A single-agent: how many rows have draft_n==0 and differ from off sha?
sha = {}
for cfg in ["off-greedy","A-greedy"]:
    for r in [json.loads(l) for l in open(f"{cfg}/requests.jsonl")]:
        if r["fg_bg"]=="fg":
            sha.setdefault((r["phase"],r["id"]), {})[cfg] = (r.get("out_sha256"), r.get("draft_n"), r.get("max_tokens"))
print("single-agent: A rows with draft_n==0, sha differs from off?")
n=0
for (p,i), d in sorted(sha.items()):
    if p!="single-agent": continue
    off, (a_sha, a_dn, a_mk) = d["off-greedy"], d["A-greedy"]
    if a_dn == 0:
        same = off[0]==a_sha[0]
        n += 1
        if not same: print(f"  {i}: off sha {off[0][:8]} A sha {a_sha[:8]} (draft 0, max_tok={a_mk}) -> DIFFER")
print(f"  count draft0: {n}")
# dual-agent sha: all differ?
diffs = sum(1 for (p,i),d in sha.items() if p=="dual-agent" and d["A-greedy"][0]!=d["off-greedy"][0])
print(f"dual-agent: A sha differs from off: {diffs}/42")
